    DEF_MIN_DOWN_SPEED = 400,
    DEF_DOWN_SPEED_LMIT = 600,
    DEF_DOWN_START_TIMEOUT_SEC = 10,
    DEF_DOWN_LIMIT_FOR_WIFI = true,
    -- 默认的下载进度通知频率
    DEF_DOWN_PROGRESS_NOTIFY_INTERVAL = 100
